    "game.gameOverMessage": "<div class=\"text-center font-bold text-red-500 text-lg my-4 p-4 border-y-2 border-red-500\">You have fallen! Game Over.<br>Please close this window and create a new world.</div>",
    "game.btn.resurrect": "Pray to the Goddess for resurrection",
