function createSafeDict(dict, fallback) {
    return new Proxy(dict, {
        get(target, prop) {
            if (typeof prop === 'string') {
                if (prop in target) return target[prop];
                if (fallback && prop in fallback) return fallback[prop];
                return '';
            }
            return target[prop];
        }
    });
}

const safeZhCN = createSafeDict(rawData['zh-CN'], rawData['zh-TW']);
const safeZhTW = createSafeDict(rawData['zh-TW'], rawData['zh-CN']);
const safeEn = createSafeDict(rawData['en'], rawData['zh-CN']);
const safeJa = createSafeDict(rawData['ja'], rawData['zh-CN']);

const baseI18nData = {
    'zh-CN': safeZhCN,
    'zh-TW': safeZhTW,
    'en': safeEn,
    'ja': safeJa,
    'zh': safeZhCN
};

export const i18nData = new Proxy(baseI18nData, {
    get(target, prop) {
        if (prop in target) return target[prop];
        if (typeof prop === 'string') {
            const lower = prop.toLowerCase();
            if (lower.startsWith('zh-cn') || lower === 'zh' || lower.includes('hans') || lower.includes('cn')) {
                return target['zh-CN'];
            }
            if (lower.startsWith('zh-tw') || lower.includes('hant') || lower.includes('tw') || lower.includes('hk')) {
                return target['zh-TW'];
            }
            if (lower.startsWith('en')) {
                return target['en'];
            }
            if (lower.startsWith('ja') || lower.startsWith('jp')) {
                return target['ja'];
            }
        }
        return target['zh-CN'] || target['zh-TW'];
    }
});
